// Ambient types for what the game and its tools hang off `window` (dev hooks, options, the
// debug panels). Type-only: node's strip mode and tools/rewrite/build-web.mjs both skip .d.ts,
// so nothing here ships. Written by tools/rewrite/add-types.mjs.

// One row of the field animation debug overlay (web/game/render.ts drawAnimDebug).
interface AnimDebugRow {
  x: number;
  y: number;
  label: string;
  sprite: string;
  /** the clip/mode readout printed beside the sprite; shape is per-draw, so it stays loose */
  info: any;
}

